    // Stored as _xlfn._xlws.NAME.
    private const string Worksheet = "FILTER 2 3|SORT 1 4";

    /// <summary>Every known function by its upper-case name.</summary>
    internal static readonly IReadOnlyDictionary<string, (int Min, int Max, string Prefix)> Functions = Table();

    private static Dictionary<string, (int Min, int Max, string Prefix)> Table()
    {
        var table = new Dictionary<string, (int, int, string)>(StringComparer.Ordinal);
        foreach (var (list, prefix) in new[] { (Classic, string.Empty), (Newer, "_xlfn."), (Worksheet, "_xlfn._xlws.") })
        {
            foreach (var entry in list.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
            {
                var parts = entry.Split(' ');
                table.Add(parts[0], (int.Parse(parts[1], CultureInfo.InvariantCulture), parts[2] == "*" ? Many : int.Parse(parts[2], CultureInfo.InvariantCulture), prefix));
            }
        }

        return table;
    }
